M2C_UNK releaseTextPopupNode();                      /* extern */
M2C_UNK freeMenuItemRecord(s32);                         /* extern */
M2C_UNK freeMenuMarkers();                            /* extern */

/* Frees the menu item record stored in *itemSlot, clears the slot, then releases the menu markers and cache block. */ void releaseMenuItemAndMarkers(s32 *itemSlot) {
    s32 item;

    item = *itemSlot;
    if (item != 0) {
        freeMenuItemRecord(item);
        *itemSlot = 0;
        freeMenuMarkers();
        releaseTextPopupNode();
    }
}
